```csharp
internal static AnalyzerSourceModel Build(
    IReadOnlyDictionary<string, string>? replacements = null,
    IReadOnlyDictionary<string, string>? additions = null);

internal Compilation Compilation { get; }
internal IReadOnlyList<INamedTypeSymbol> AnalyzerTypes { get; }              // everything deriving from DiagnosticAnalyzer
internal IReadOnlyList<Registration> Registrations { get; }                  // resolved Roslyn Register* calls + their kind/constant arguments
